-- Mod-authored natural wonder portrait descriptions, pt_BR overlay.
-- Baseline in CivVAccess_NaturalWonderDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_MISSING"] = "Nenhuma descrição para esta maravilha natural."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_CRATER"] =
    "Uma vasta cratera de impacto vista da sua borda, uma tigela irregular socada no pálido solo do deserto. A encosta próxima é coberta por mato verde que despenca para o poço sombreado, cujo fundo jaz em uma escuridão marrom profunda, e a borda distante se ergue em faixas de castanho e dourado sob um céu enevoado."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_EL_DORADO"] =
    "Uma pirâmide escalonada de ouro maciço, com uma íngreme escadaria subindo sua face até um pequeno santuário no topo. Gigantescos lingotes de ouro estão empilhados em sua base entre árvores escuras e esguias, e toda a cena resplandece em amarelo, o tesouro da cidade mítica tornado literal. Os raios de luz por trás dela parecem um nascer do sol despontando sobre a cidade perdida."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FOUNTAIN_YOUTH"] =
    "Uma fonte de água turquesa impossivelmente brilhante brota de uma bacia sobre falésias de rocha escura e despenca como uma cachoeira luminosa para a poça abaixo. Tufos de grama verde se agarram à rocha negra, frondes de palmeira emolduram um céu dourado e quente, e diminutos brilhos na água a marcam como mágica e não natural."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FUJI"] =
    "Um cone vulcânico perfeito preenche o quadro, sua larga capa de neve alcançando boa parte das encostas. A neve é pintada em branco suave e azul pálido contra um céu azul profundo, e uma faixa de mato verde e água enevoada se estende ao longo do sopé da montanha."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GEYSER"] =
    "Um gêiser irrompe de um pálido montículo escarpado, sua aspersão branca abrindo-se em leque para preencher todo o céu de névoa contra o azul. Floresta escura de coníferas se fecha de ambos os lados, e o primeiro plano é uma crosta de terraços minerais em castanho, ocre e marrom."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GIBRALTAR"] =
    "Um grande promontório de calcário se ergue de um mar plano, falésias pálidas e a pique na face esquerda e uma longa encosta de vegetação verde escura descendo por suas costas. Toda a cena é banhada em ouro, o céu e a água resplandecendo como no fim da tarde."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_KILIMANJARO"] =
    "Um enorme domo riscado de neve preenche a metade superior do quadro em branco e azul gélidos, com um anel de pequenas nuvens vagando em sua base. Abaixo dele se estende a savana verde onde duas girafas estão junto a um pálido bebedouro, árvores de copa achatada nas bordas da cena."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_LAKE_VICTORIA"] =
    "Um largo lago turquesa se estende ao fundo até colinas pálidas no horizonte, cercado por afloramentos rochosos castanhos de ambos os lados. No centro do primeiro plano um hipopótamo emerge, sua cabeça e dorso rompendo a água encrespada, sob um branco resplendor de luz que preenche o céu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MESA"] =
    "Uma mesa de topo plano feita de rocha vermelho-alaranjada em camadas se ergue sozinha de uma planície seca, paredes de falésia listradas acima de longas encostas de rocha caída. Mato verde esparso pontilha o solo arenoso ao seu pé, e o cume plano corta uma linha dura contra um céu azul brilhante."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_KAILASH"] =
    "Uma pirâmide de rocha listrada e neve se ergue contra um céu azul profundo, sua face estriada iluminada de dourado quente em um lado. Abaixo dela o primeiro plano é todo campo de neve áspero e cristas de gelo em fria sombra azul."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_SINAI"] =
    "Um aglomerado de picos escarpados de deserto em arenito laranja-amarronzado, ravinas profundas riscando suas faces, com um suave resplendor de luz despontando por trás do cume central. Pedregulhos espalhados cobrem o plano arenoso no primeiro plano sob um céu azul límpido."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_POTOSI"] =
    "Uma montanha de um vermelho-amarronzado nu cujas encostas inferiores estão soterradas sob amontoados de pedregulhos cinzentos cintilando com minério de prata. Uma trilha serpenteia por seu flanco, fileiras de blocos escuros e esquadriados alinham sua base como escavações de mina, e o cume empoeirado se destaca contra um céu azul."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_REEF"] =
    "Uma cena submarina: corais se aglomeram à esquerda e na base do quadro em laranja, vermelho, roxo e azul pálido, com esponjas tubulares eretas entre os ramos. Pequenos peixes tropicais flutuam pela água azul profunda, um amarelo brilhante no centro. A luz esmaece em escuridão aberta na direção do canto superior direito."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SOLOMONS_MINES"] =
    "Uma monumental casa de portão que representa as lendárias minas: uma alta muralha de fortaleza escura coroada por ameias com pontas douradas, uma entrada em seu centro, ladeada por torres de pedra castanha. Diante dela o pálido piso de rocha é esculpido em curvas amplas, como se o próprio solo tivesse sido lavrado liso."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SRI_PADA"] =
    "Uma exuberante montanha verde se ergue até um pico arredondado, a selva cobrindo suas encostas exceto onde a rocha laranja-amarronzada irrompe em falésias. Altas lâminas de grama com pequenas flores azuis preenchem o primeiro plano, e o céu por trás é um vívido turquesa tropical."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_ULURU"] =
    "Um grande monólito vermelho repousa atravessado na distância média, sua massa arredondada de arenito sulcada por ranhuras verticais e resplandecendo em laranja sob a luz. Diante dele se estende o mato plano do interior, terra vermelha remendada de mato verde baixo e tufos de grama, sob um céu azul brilhante."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_VOLCANO"] =
    "Um cone vulcânico escuro se ergue do mar além de uma faixa de água turquesa pálida, visto de uma costa de selva cujas largas folhas verdes emolduram a cena. O céu acima dele arde em amarelo sulfúrico, com uma fina espiral de fumaça sobre o cume insinuando a erupção que está por vir."
